// media helper: instance an asset from 04 Media by name
function asset(name){ return media.findOne(n=>n.name===name && (n.type==='COMPONENT')); }
function inst(name, parent, x, y, targetW){
  const src = asset(name); if(!src) throw new Error('missing asset '+name);
  const i = src.createInstance();
  if (targetW){ const s = targetW/src.width; i.rescale(s); }
  parent.appendChild(i); i.x=x; i.y=y; return i;
}
function logoInstance(name, parent, x, y, box){
  const src = asset(name);
  const i = src.createInstance();
  const s = Math.min(box/src.width, box/src.height);
  i.rescale(s);
  parent.appendChild(i); i.x = x + (box - i.width)/2; i.y = y + (box - i.height)/2;
  return i;
}

