    try { t.textAutoResize='WIDTH_AND_HEIGHT'; t.lineHeight={unit:'PIXELS',value:20}; t.layoutSizingHorizontal='HUG'; } catch(e){}
  });
};
fixField(figma.getNodeById('7:20'));
for (const f of ws.children){
  if(f.type!=='FRAME') continue;
  f.findAll(n=>n.type==='INSTANCE' && n.name==='C/TextField').forEach(fixField);
}

// ---- 2. prototype wiring: skip self-navigation, guard each link ----
const frame = name => ws.children.find(n=>n.name===name && n.type==='FRAME');
const F = { splash:frame('01_Splash'), onb:frame('02_Onboarding'), empty:frame('03_Sign_Up_Empty'), filled:frame('03_Sign_Up_Filled'), phone:frame('04_Verify_Phone'), code:frame('05_Verify_Code'), welcome:frame('06_Welcome'), home:frame('07_Home'), port:frame('08_Portfolio'), detail:frame('09_Stock_Detail'), order:frame('10_Confirm_Order'), profile:frame('11_Profile') };
const TRANS = {type:'DISSOLVE', duration:0.28, easing:{type:'EASE_OUT'}};
const done=[], failed=[];
const link = (k, node, dest, trigger) => {
  if (!node || !dest || node.id===dest.id) { failed.push(k+' (no source/self)'); return; }
  try {
    node.reactions = [{ trigger: trigger||{type:'ON_CLICK'}, actions:[{ type:'NODE', navigation:'NAVIGATE', destinationId: dest.id, transition: TRANS, resetScrollPosition: true }] }];
    done.push(k);
  } catch(e){ failed.push(k+' :: '+e.message.slice(0,110)); }
};
const btn = (parent,label) => parent.findOne(n=>n.type==='INSTANCE' && n.name==='C/Button' && n.findAll(t=>t.type==='TEXT').some(t=>t.characters===label));
const tab = (parent,label) => parent.findAll(n=>n.type==='FRAME' && n.name==='Tab '+label)[0];
const textNode = (parent,label) => parent.findAll(n=>n.type==='TEXT').find(t=>t.characters===label);
const backIn = f => f.children.find(c=>c.name==='Back');

link('01 splash → 02', F.splash, F.onb, {type:'AFTER_TIMEOUT', timeout:1.8});
link('02 Sign up → 03 empty', btn(F.onb,'Sign up'), F.empty);
link('02 Skip → 03 empty', textNode(F.onb,'Skip'), F.empty);
link('02 Sign in → 03 empty', btn(F.onb,'Sign in'), F.empty);
link('03 filled Continue → 04', btn(F.filled,'Continue'), F.phone);
link('04 back → 03 filled', backIn(F.phone), F.filled);
link('04 Send code → 05', btn(F.phone,'Send code'), F.code);
link('05 back → 04', backIn(F.code), F.phone);
link('05 Verify account → 06', btn(F.code,'Verify account'), F.welcome);
link('06 ready → 07', btn(F.welcome,'I’m ready to start!'), F.home);

const navMap = {Home:F.home, Portfolio:F.port, Trade:F.order, Profile:F.profile};
const wireTabs = (f, prefix) => {
  Object.keys(navMap).forEach(l=>{
    const dest = navMap[l];
    if (dest.id === f.id) { return; } // current tab: no self navigation
    link(prefix+' tab '+l, tab(f,l), dest);
  });
};
wireTabs(F.home,'07'); wireTabs(F.port,'08'); wireTabs(F.profile,'11');

link('07 card → 08', F.home.children.find(c=>c.name==='Portfolio card'), F.port);
link('07 NFLX row → 09', F.home.children.find(c=>c.name==='Row NFLX'), F.detail);
link('08 back → 07', backIn(F.port), F.home);
link('08 NFLX row → 09', F.port.children.find(c=>c.name==='Row NFLX'), F.detail);
link('09 back → 07', backIn(F.detail), F.home);
link('09 Buy stocks → 10', btn(F.detail,'Buy stocks'), F.order);
link('10 back → 09', backIn(F.order), F.detail);
link('10 Confirm order → 07', btn(F.order,'Confirm order'), F.home);

ws.flowStartingPoints = [{nodeId: F.splash.id, name:'StockWave · full flow'}];
return {done, failed, total:done.length};

